 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != 0]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    frame = grid[r0][c0]
    accent = next(value for row in grid for value in row if value not in (0, frame))
    # Expand the frame outwards by one cell, using its inner/accent color;
    # retain the original framed pattern, including any accent marker.
    for r in range(max(0, r0 - 1), min(len(out), r1 + 2)):
        for c in range(max(0, c0 - 1), min(len(out[0]), c1 + 2)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = accent
    return out
